  @Nullable
  public static Interval findOverlappingInterval(Interval searchInterval, Interval[] sortedIntervals)
  {
    return VersionedIntervalTimeline.findOverlappingInterval(searchInterval, sortedIntervals);
  }

  private Intervals()
  {
  }
}

